e OR OLD.supplier_id IS NOT NEW.supplier_id OR OLD.setup_hours IS NOT NEW.setup_hours OR OLD.unit_hours IS NOT NEW.unit_hours OR OLD.ext_days IS NOT NEW.ext_days OR OLD.batch_id IS NOT NEW.batch_id),NEW.id,NEW.op_code,NEW.batch_id,NEW.piece_id,NEW.seq,NEW.op_type_id,NEW.op_type_name,NEW.source,NEW.machine_id,NEW.operator_id,NEW.supplier_id,NEW.setup_hours,NEW.unit_hours,NEW.ext_days,NEW.status,NEW.created_at,(SELECT ref FROM WorkbenchEntityRefs WHERE kind=''batch'' AND active=1 AND entity_key=b.batch_id),(SELECT ref FROM WorkbenchEntityRefs WHERE kind=''part'' AND active=1 AND entity_key=b.part_no),b.quantity FROM Batches b WHERE b.batch_id=NEW.batch_id AND (SELECT ref FROM WorkbenchPlanSourceRefs WHERE kind=''operation'' AND active=1 AND source_key=CAST(OLD.id AS TEXT)) IS NOT NULL; END"],["trigger","wb_lineage_origin_birth","WorkbenchTemplateLineageOrigins","CREATE TRIGGER wb_lineage_origin_birth BEFORE INSERT ON WorkbenchTemplateLineageOrigins BEGIN\n        SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM WorkbenchTemplateLineageEvents e\n            JOIN WorkbenchPlanSourceRefs r ON r.ref=e.operation_ref AND r.kind=''operation'' AND r.active=1\n            WHERE e.event_id=NEW.birth_event_id AND e.operation_ref=NEW.operation_ref AND e.event_type=''created'')\n            THEN RAISE(ABORT,''template lineage requires a new instance birth'') END;\n        SELECT CASE WHEN EXISTS (SELECT 1 FROM WorkbenchTemplateLineageOrigins WHERE operation_ref=NEW.operation_ref OR lineage_ref=NEW.lineage_ref)\n            THEN RAISE(ABORT,''template lineage cannot be rebound'') END;\n    END"],["trigger","wb_lineage_origin_no_delete","WorkbenchTemplateLineageOrigins","CREATE TRIGGER wb_lineage_origin_no_delete BEFORE DELETE ON WorkbenchTemplateLineageOrigins BEGIN SELECT RAISE(ABORT,''template lineage is append-only''); END"],["trigger","wb_lineage_origin_no_update","WorkbenchTemplateLineageOrigins","CREATE TRIGGER wb_lineage_origin_no_update BEFORE UPDATE ON WorkbenchTemplateLineageOr